# -*- coding: utf-8 -*-
# 第 12 批（J4）：環境教育設施場所認證及管理辦法（ENV-205）第1條～第20條；環境教育機構認證及管理辦法（ENV-206）第1條～第21條
S = "ENV-205"
G = "ENV-206"
Q = [
(S,"第1條",1,"設施場所-授權依據",
 "環境教育設施場所認證及管理辦法係依據下列何項規定訂定？",
 ["環境教育法第十四條第三項","環境教育法第十條第三項規定","環境教育法第十九條第二項規定","環境基本法第十四條第三項規定"],"a",
 "第1條：本辦法依環境教育法第14條第3項規定訂定之。環境教育機構認證及管理辦法則依本法第10條第3項訂定。第20條並定本辦法自發布日施行。",
 "Under which provision are the Environmental Education Facility Regulations issued?",
 ["Article 14, Paragraph 3 of the Environmental Education Act","Article 10, Paragraph 3 of the Environmental Education Act","Article 19, Paragraph 2 of the Environmental Education Act","Article 14, Paragraph 3 of the Basic Environment Act"],
 "Article 1."),

(S,"第2條",2,"設施場所-定義",
 "本辦法所稱環境教育設施、場所之定義為何？",
 ["指整合環境教育專業人力、課程方案及經營管理，用以提供環境教育專業服務之具有豐富自然或人文特色之空間、場域、裝置或設備","指由政府機關興建並委託民間經營，專供學校戶外教學使用之具有自然生態或人文歷史價值之園區、館舍、步道或展示設施","指依環境教育法取得認證之環境教育人員所設立，並以營利為目的對外招收學員辦理環境講習課程之教室、場館或訓練中心","指經中央主管機關公告列為國家重要濕地、自然保留區或國家公園範圍內，供民眾自由參觀而不收取任何費用之開放空間"],"a",
 "第2條：本辦法所稱環境教育設施、場所，指整合環境教育專業人力、課程方案及經營管理，用以提供環境教育專業服務之具有豐富自然或人文特色之空間、場域、裝置或設備。第3條並要求設置應尊重生命、維護生態、保護環境並與在地環境資源及特色結合。",
 "How are environmental education facilities and sites defined?",
 ["Spaces, fields, installations or equipment rich in natural or cultural features that integrate professional staff, curriculum programmes and management to provide professional services","Parks, halls, trails or exhibits of ecological or historical value built by government and contracted to the private sector solely for school outdoor teaching use","Classrooms, halls or training centres set up by certified environmental education personnel that recruit students for profit and run environmental lecture courses","Open spaces within announced national important wetlands, nature reserves or national park boundaries that the general public may visit freely without paying any admission fee at all"],
 "Article 2."),

(S,"第3條",2,"設施場所-設置原則",
 "設施場所之設置，應遵循之原則為何？",
 ["應尊重生命、維護生態、保護環境，並與在地環境資源及特色結合，避免興建不必要之人工裝置、鋪設或設備","應優先考量遊客量之最大化及營運收益，並得視需要興建各類人工裝置、鋪設或設備以提升參觀者之體驗品質","應設置於都市計畫區內交通便利之處，並與鄰近觀光遊憩據點結合，興建足供大型遊覽車停放之停車場及商店設施","應由中央主管機關統一規劃設計並編列預算興建，地方主管機關及民間團體不得自行設置或提出設施場所認證申請"],"a",
 "第3條：設施場所之設置，應尊重生命、維護生態、保護環境，並與在地環境資源及特色結合，避免興建不必要之人工裝置、鋪設或設備。第2條並定義設施場所應具有豐富自然或人文特色。",
 "What principles govern the establishment of a facility or site?",
 ["Respect life, maintain ecology and protect the environment, link with local environmental resources and features, and avoid unnecessary artificial installations or paving","Maximize visitor numbers and operating revenue, building artificial installations, paving and equipment as needed to improve the visitor experience","Locate within urban planning areas with convenient transport, link with nearby tourist spots, and build coach parking and shops for visitors","Be planned, budgeted and built solely by the central competent authority, with local competent authorities and private organizations barred from setting up or applying"],
 "Article 3."),

(S,"第4條",3,"設施場所-申請文件",
 "申請設施場所認證所檢具之計畫書，應包括之內容為何？",
 ["環境現況及自然或人文特色主題內容說明、環境教育專業人力配置說明、與保護環境連結之環境教育課程方案、經營管理規劃、近三年辦理環境教育相關證明","訓練場所之所有權或使用權證明、負責人身分證明、預定開辦之課程科目及授課師資、授課章節大綱及配合推廣環境政策之相關執行措施說明","設施場所之土地登記謄本及地價證明、建築物使用執照影本、消防安全檢查合格證明、公共意外責任保險證明及環境影響評估審查結論","近五年之財務報表及會計師查核簽證報告、員工勞健保投保清冊、遊客人數統計資料、門票收費標準表及與旅行社簽訂之合作契約書"],"a",
 "第4條第1項第3款：計畫書內容為環境現況、自然或人文特色主題及內容之說明；環境教育專業人力配置說明（至少應配置一名依本法取得認證之環境教育人員）；與保護環境連結之環境教育課程方案；經營管理規劃（含能力、經歷、人員增能培力、安全維護、環境負荷、營運目標、財務計畫及配合國家政策之配套措施）；近三年辦理環境教育相關證明。",
 "What must the plan submitted with a facility certification application contain?",
 ["Current environmental conditions and thematic features, professional staffing, curriculum programmes linked to environmental protection, management planning, and three-year activity proof","Ownership or use rights of the training venue, the representative identity proof, planned course subjects and instructors, syllabi, and policy promotion measures","Land registration transcripts and value certificates, the building use licence, fire safety certificates, public liability insurance, and EIA review conclusions","Five years of financial statements with certified auditor reports, labour insurance rosters, visitor statistics, the ticket price schedule, and cooperation contracts signed with travel agencies"],
 "Article 4, Paragraph 1, Subparagraph 3."),

(S,"第4條",3,"設施場所-人員訓練",
 "設施場所所配置之環境教育人員，於何種情形應另附訓練證明？其時數為何？",
 ["連續三年以上未經依本法配置於環境教育機構或環境教育設施場所者，應附申請日前一年內參加法規或政策相關訓練三小時以上之證明文件","連續一年以上未經依本法配置於環境教育機構或環境教育設施場所者，應附申請日前三個月內參加法規或政策相關訓練八小時以上之證明","連續五年以上未經依本法配置於環境教育機構或環境教育設施場所者，應附申請日前二年內參加法規或政策相關訓練二十小時以上證明","凡經依本法取得環境教育人員認證者，一律應附申請日前一年內參加法規或政策相關訓練二十四小時以上之訓練合格證明文件"],"a",
 "第4條第2項：配置之環境教育人員，連續三年以上未經依本法配置於環境教育機構或環境教育設施場所者，應附該人員於申請日前一年內參加各級主管機關或其委託機構辦理環境教育法規或政策相關訓練三小時以上之證明文件。第4條第1項第3款第2目並要求至少配置一名依本法取得認證之環境教育人員。",
 "When must extra training proof be filed for the assigned environmental education personnel?",
 ["Where the person has not been assigned to a certified institution or facility for three consecutive years, proof of at least three hours of law or policy training within the past year is required","Where the person has not been assigned to a certified institution or facility for one consecutive year, proof of at least eight hours of law or policy training within three months is required","Where the person has not been assigned to a certified institution or facility for five consecutive years, proof of at least twenty hours of law or policy training within two years is required","Every certified environmental education person must always file proof of at least twenty-four hours of law or policy training completed within the year before the application"],
 "Article 4, Paragraph 2."),

(S,"第5條",1,"設施場所-審查費",
 "申請設施場所認證時，應繳納之審查費為多少？",
 ["新臺幣五千元","新臺幣一萬元","新臺幣二千五百元","新臺幣二萬五千元"],"a",
 "第5條：申請人依第4條提出申請時，應繳納審查費新臺幣五千元。第9條第1項展延審查費為新臺幣二千五百元；第10條並定除依規費法規定得申請退還外，不得以任何理由要求退費或保留。",
 "What review fee is payable when applying for facility certification?",
 ["NT$5,000","NT$10,000","NT$2,500","NT$25,000"],
 "Article 5."),

(S,"第6條",2,"設施場所-審查期限",
 "中央主管機關辦理設施場所認證審查之期限規定為何？",
 ["應於收到申請文件及審查費次日起三個月內完成審查；必要時得延長，合計不得逾六個月，補正日數不計入審查期間","應於收到申請文件及審查費次日起一個月內完成審查；必要時得延長，合計不得逾三個月，補正日數計入審查期間","應於收到申請文件及審查費次日起六個月內完成審查；必要時得延長，合計不得逾一年，補正日數計入審查期間內","應於收到申請文件及審查費次日起九十日內完成審查；不得延長，補正日數計入審查期間且補正次數以一次為限"],"a",
 "第6條第1項：中央主管機關應於收到申請文件及審查費次日起三個月內完成設施場所認證審查；經審查應補正者應通知限期補正，逾期未補正、補正不完全或無法補正者駁回其申請。第2項：審查期間必要時得延長之，合計不得逾六個月；補正日數不計入審查期間。",
 "What is the review period for facility certification?",
 ["Three months from the day after the documents and fee are received, extendable to no more than six months in total, with supplementation days excluded","One month from the day after the documents and fee are received, extendable to no more than three months in total, with supplementation days counted","Six months from the day after the documents and fee are received, extendable to no more than one year in total, with supplementation days counted","Ninety days from the day after the documents and fee are received, not extendable, with supplementation days counted and only one round allowed"],
 "Article 6."),

(S,"第7條",2,"設施場所-審查會",
 "中央主管機關辦理設施場所認證審查時，關於審查組織及程序之規定為何？",
 ["應邀集相關機關及專家學者參與審查並得成立審查會；審查會開會前得徵詢專家學者及相關機關團體意見，召開初審會議並將初審結果提報審查會審查","應由中央主管機關承辦人員逕行書面審查後簽陳核定；不得邀集外部專家學者參與，亦不得成立審查會或召開任何形式之初審會議","應委由申請人所在地之直轄市或縣市主管機關代為實地審查並作成建議，中央主管機關依其建議逕予核定，無須另行召開審查會議","應由中央主管機關就申請案件公開徵求民眾意見三十日後，交由環境教育審議委員會以投票方式表決，經過半數同意者始得通過"],"a",
 "第7條第1項：中央主管機關辦理設施場所之認證，應邀集相關機關及專家學者參與審查，並得成立審查會辦理相關作業。第2項：審查會開會前，得徵詢有關專家學者及相關機關、團體意見，召開初審會議，初審結果提報審查會審查。",
 "How is the certification review organized?",
 ["Relevant agencies and experts are invited and a review panel may be set up; before it meets, opinions may be sought and a preliminary meeting held whose results go to the panel","Staff of the central competent authority review the documents alone and submit them for approval; no outside experts, review panel or preliminary meeting is permitted","The local competent authority conducts the field review and gives its recommendation, on which the central authority decides without convening any review panel","The authority seeks public comments for thirty days and then puts the case to a vote of the environmental education committee, requiring a simple majority"],
 "Article 7."),

(S,"第8條",2,"設施場所-認證文件",
 "中央主管機關核發之設施場所認證證明文件，其應記載事項及陳列規定為何？",
 ["應記載設施場所名稱及地址或座落位置、申請人名稱及負責人姓名、核發機關、核准日期字號、有效期限；並應陳列於設施場所明顯處","應記載設施場所名稱及地址、環境教育人員姓名及認證字號、課程方案名稱、收費標準、參觀人數上限；並應陳列於設施場所明顯處","應記載設施場所名稱及地址、土地地號及面積、建物構造及樓層數、消防設備配置、緊急聯絡電話；並應公告於中央主管機關網站","應記載設施場所名稱及地址、評鑑等級及分數、歷年執行成果統計、財務收支概況、未來營運計畫；並應陳列於設施場所之入口處"],"a",
 "第8條第1項：認證證明文件應記載設施場所名稱及地址或座落位置、申請人名稱及負責人姓名、核發機關、核准日期及字號、有效期限。第2項：認證證明文件應陳列於設施場所明顯處。第18條並定認證之核發、撤銷或廢止應公開於中央主管機關網站。",
 "What must the certification document state, and where must it be displayed?",
 ["The facility name and address or location, applicant name and representative, issuing agency, approval date and number, and validity period; displayed in a conspicuous place","The facility name and address, the personnel name and certificate number, programme names, fee schedule and visitor cap; displayed in a conspicuous place at the site","The facility name and address, land parcel and area, building structure and floors, fire equipment layout and emergency numbers; published on the authority website","The facility name and address, assessment grade and score, historical performance statistics, finances and future plans; displayed at the entrance of the facility"],
 "Article 8."),

(S,"第9條",3,"設施場所-展延",
 "設施場所認證之有效期限及展延申請規定為何？",
 ["有效期限為五年；期限屆滿前三至六個月期間內得檢具申請書、經營管理規劃、最近一次評鑑建議回覆表等文件並繳交展延審查費新臺幣二千五百元申請展延，每次展延有效期限為五年","有效期限為三年；期限屆滿前一至二個月期間內得檢具申請書、經營管理規劃、最近一次評鑑建議回覆表等文件並繳交展延審查費新臺幣五千元申請展延，每次展延有效期限為三年","有效期限為十年；期限屆滿後六個月內得檢具申請書及經營管理規劃等文件並繳交展延審查費新臺幣一萬元申請展延，每次展延之有效期限則為十年並得無限次數展延","有效期限為五年；期限屆滿前一年至屆滿當日止均得隨時檢具申請書申請展延且免繳交任何展延審查費用，每次展延之有效期限由中央主管機關個案核定之"],"a",
 "第9條第1項：設施場所之認證有效期限為五年；期限屆滿前三至六個月期間內，得檢具申請書、經營管理規劃、最近一次評鑑建議回覆表及其他經中央主管機關指定之文件，並繳交展延審查費新臺幣二千五百元，向中央主管機關申請展延；每次展延之有效期限為五年。第5項並定審查期限三個月，必要時得延長合計不得逾六個月。",
 "What are the certification validity and renewal rules for a facility?",
 ["Valid five years; apply three to six months before expiry with the application, management plan and latest assessment response, paying an NT$2,500 renewal fee; each renewal lasts five years","Valid three years; apply one to two months before expiry with the application, management plan and latest assessment response, paying an NT$5,000 renewal fee; each renewal lasts three years","Valid ten years; apply within six months after expiry with the application and management plan, paying an NT$10,000 renewal fee; each renewal lasts ten years with unlimited renewals","Valid five years; apply at any time from one year before expiry until the expiry date itself with no renewal fee at all, each renewal period being decided case by case"],
 "Article 9, Paragraph 1."),

(S,"第9條",3,"設施場所-展延效果",
 "設施場所未依規定期間申請展延或未於期限屆滿前申請展延者，其效果為何？",
 ["未依規定期間申請者，中央主管機關於期限屆滿尚未完成審查時，應自期限屆滿時起停止以認證設施場所名義經營業務；未於期限屆滿前申請者，認證於期限屆滿時失其效力","未依規定期間申請者，仍得於審查期間內依原認證內容繼續辦理業務；未於期限屆滿前申請者，得於屆滿後六個月內補行申請，認證效力自始不受任何影響","未依規定期間申請者，中央主管機關應逕予廢止其認證並公開於網站；未於期限屆滿前申請者，其認證自動展延一年，俟次年再行申請展延即可繼續經營","未依規定期間申請者，應加倍繳納展延審查費後即可繼續營運；未於期限屆滿前申請者，中央主管機關應命其限期補行申請，屆期未申請始失其效力"],"a",
 "第9條第2項：依規定期間申請展延者，中央主管機關於有效期限屆滿尚未完成審查時，設施場所於審查期間內得依原認證內容辦理。第3項：未依第1項規定期間申請展延者，於期限屆滿尚未完成審查時，應自期限屆滿時起停止以認證設施場所名義經營業務。第4項：未於期限屆滿前申請展延者，於期限屆滿時認證失其效力，如需繼續經營應重新申請認證。",
 "What follows when renewal is applied for late or not at all?",
 ["If applied late and review is unfinished at expiry, operating under the certified name must stop from expiry; if never applied for, the certification lapses at expiry","If applied late, operations may still continue under the original certification during review; if never applied for, a late application within six months preserves the effect","If applied late, the authority revokes the certification and publishes it online; if never applied for, the certification is automatically extended by one year","If applied late, doubling the renewal fee allows continued operation; if never applied for, the authority must order a late application before any lapse"],
 "Article 9, Paragraphs 3 and 4."),

(S,"第10條",1,"設施場所-規費退還",
 "依規定繳交之設施場所認證審查費及展延審查費，得否要求退費？",
 ["除依規費法規定得申請退還外，不得以任何理由要求退費或保留","申請案件經駁回者，得申請全額退還已繳納之審查費用","申請人於審查完成前撤回申請者，得申請退還半數審查費","得由申請人選擇退費或保留於次年度申請時抵充審查費用"],"a",
 "第10條：依第5條及第9條第1項規定繳交之審查費，除依規費法規定得申請退還外，不得以任何理由要求退費或保留。第5條認證審查費為新臺幣五千元，第9條第1項展延審查費為新臺幣二千五百元。",
 "May the review or renewal fee be refunded?",
 ["Except where the Fee Act allows a refund, no refund or carry-over may be demanded on any ground","If the application is rejected, the full review fee already paid may be claimed back in refund","If the applicant withdraws before the review ends, half of the review fee may be refunded","The applicant may choose a refund or carry the fee over to offset next year application"],
 "Article 10."),

(S,"第11條",1,"設施場所-調訓",
 "中央主管機關對依本辦法配置之環境教育人員，有何調訓權限？",
 ["得於必要時調訓該等人員，設施場所不得以任何方式妨礙其參訓","得於必要時調訓該等人員，惟設施場所得以業務繁忙為由拒絕派員","僅得於認證審查期間要求該等人員參訓，認證後即不得再行調訓","應委由環境教育機構辦理調訓，中央主管機關不得逕行調訓人員"],"a",
 "第11條第1項：中央主管機關於必要時得調訓依本辦法配置之環境教育人員。第2項：設施場所不得以任何方式妨礙前項人員參訓。第4條第1項第3款第2目並要求至少配置一名依本法取得認證之環境教育人員。",
 "What power does the authority have to call assigned personnel for training?",
 ["It may call them for training when necessary, and the facility may not obstruct their attendance in any way","It may call them for training when necessary, but the facility may refuse on grounds of a heavy workload","It may require attendance only during the certification review, and never after certification is granted","It must have a certified institution run the training, and may not summon the personnel by itself"],
 "Article 11."),

(S,"第12條",2,"設施場所-文件異動",
 "設施場所申請認證所送文件有異動時，應如何辦理？",
 ["除環境教育課程方案文件應於報請中央主管機關核准後始得變更外，其餘應於異動後十五日內報請中央主管機關備查","除環境教育專業人力配置說明應於報請中央主管機關核准後始得變更外，其餘應於異動後三十日內報請中央主管機關備查","所有異動文件均應於報請中央主管機關核准後始得變更，未經核准而逕行變更者，中央主管機關應撤銷其認證資格","所有異動文件均得由設施場所自行變更並留存備查，僅需於每季執行成果申報時併同說明異動內容及理由即可"],"a",
 "第12條：設施場所申請認證所送文件有異動時，除第4條第1項第3款第3目之文件（與保護環境連結之環境教育課程方案）應於報請中央主管機關核准後始得變更外，應於異動後十五日內報請中央主管機關備查。第17條第1項第9款並定實際經營管理與申請文件不符經限期改善屆期未改善者得廢止認證。",
 "How must changes to the submitted application documents be handled?",
 ["Except the environmental education curriculum programme, which needs prior approval before change, changes are filed for recordation within fifteen days","Except the professional staffing statement, which needs prior approval before change, changes are filed for recordation within thirty days of the change","All changed documents require prior approval before any change, and unapproved changes lead the authority to revoke the certification","All documents may be changed by the facility itself and merely explained in the quarterly performance report along with the reasons"],
 "Article 12."),

(S,"第13條",1,"設施場所-成果申報",
 "認證之設施場所應如何申報環境教育執行成果？",
 ["應於每季依中央主管機關要求之格式，以網路傳輸方式申報前一季環境教育執行成果","應於每年年底依中央主管機關要求之格式，以書面郵寄方式申報當年度執行成果","應於每月十日前依中央主管機關要求之格式，以傳真方式申報前一月執行成果","應於每二年依中央主管機關要求之格式，以現場簡報方式申報前二年執行成果"],"a",
 "第13條：認證之設施場所應於每季依中央主管機關要求之格式，以網路傳輸方式申報前一季環境教育執行成果。第17條第1項第1款並定環境教育執行成果內容不實者，中央主管機關得廢止其認證。",
 "How must a certified facility report its environmental education performance?",
 ["Quarterly, in the format required by the authority, transmitted online for the preceding quarter","Annually at year end, in the format required by the authority, mailed in paper for that year","By the tenth of each month, in the format required by the authority, faxed for the prior month","Every two years, in the format required by the authority, presented on site for those years"],
 "Article 13."),

(S,"第14條",1,"設施場所-訪查",
 "中央主管機關對認證之設施場所有何訪查權限？",
 ["得隨時派員訪查，並命其就環境教育實施狀況提供必要資料","得於每年固定期日派員訪查，並應於訪查前三十日書面通知","僅得於評鑑年度派員訪查，其餘年度不得進入設施場所查核","應會同地方主管機關始得派員訪查，且不得要求提供任何資料"],"a",
 "第14條：中央主管機關得隨時派員訪查認證之設施場所，並命其就環境教育實施狀況提供必要資料。第17條第1項第2款：無正當理由拒絕中央主管機關之訪查或提供必要資料者，中央主管機關得廢止其認證。",
 "What inspection powers apply to certified facilities?",
 ["Officers may be sent to visit at any time and may require necessary data on how education is delivered","Officers visit on a fixed date each year, with thirty days written notice given before the visit","Visits are allowed only in an assessment year, and the site may not be entered in other years","Visits require the local authority to join, and no data of any kind may be demanded"],
 "Article 14."),

(S,"第15條",2,"設施場所-評鑑",
 "中央主管機關對認證之設施場所實施評鑑之時點及受評鑑單位之義務為何？",
 ["得自行或委託學術團體或專業評鑑機構，於通過認證或展延之日當年起算第三年實施評鑑；受評鑑單位需提出評鑑自評報告","得自行或委託學術團體或專業評鑑機構，於通過認證或展延之日當年起算第五年實施評鑑；受評鑑單位無須提出任何自評報告","應由中央主管機關自行辦理不得委託，於通過認證之日當年起算第一年實施評鑑；受評鑑單位需提出財務查核報告及稽核意見","應由設施場所自行委託專業評鑑機構辦理，於認證有效期限屆滿當年實施評鑑；評鑑結果僅供內部參考無須報請主管機關備查"],"a",
 "第15條第1項：中央主管機關得自行或委託學術團體或專業評鑑機構，於通過認證或展延之日當年起算第三年，對認證之設施場所實施評鑑。第2項：受評鑑單位需提出評鑑自評報告，其格式由中央主管機關定之。第17條第1項第7款並定評鑑不合格經命限期改善屆期未改善完成者得廢止認證。",
 "When is a certified facility assessed and what must it submit?",
 ["The authority may assess itself or through academic or professional bodies in the third year counted from certification or renewal; the assessed unit files a self-assessment report","The authority may assess itself or through academic or professional bodies in the fifth year counted from certification or renewal; no self-assessment report is required","The authority must assess by itself without delegation in the first year from certification; the assessed unit files a financial audit report and audit opinion","The facility must commission a professional assessment body itself in the year the certification expires, and the results are for internal reference only"],
 "Article 15."),

(S,"第16條",1,"設施場所-撤銷認證",
 "設施場所檢送之申請文件有虛偽不實者，中央主管機關應如何處理？",
 ["應撤銷其認證","得命其限期改善，屆期未改善始撤銷認證","應處以罰鍰並命其重新提出正確之申請文件","得暫停其認證效力一年，期滿後自動回復效力"],"a",
 "第16條：設施場所依第4條及第9條第1項檢送之申請文件有虛偽不實者，中央主管機關應撤銷其認證。第17條則規定得廢止認證之十款情形；第18條並定認證之核發、撤銷或廢止應公開於中央主管機關網站。",
 "What happens if the submitted application documents are false?",
 ["The certification must be revoked","An improvement order comes first, with revocation only if unremedied","A fine is imposed together with an order to refile correct application documents","The certification is suspended for one year and then automatically restored"],
 "Article 16."),

(S,"第17條",3,"設施場所-廢止認證",
 "中央主管機關得廢止設施場所認證之情形，下列何者符合規定？",
 ["環境教育執行成果內容不實、無正當理由拒絕訪查或提供資料、申請人喪失所有權管理權或使用權、未提供環境教育服務持續達一年以上、評鑑不合格經命限期改善屆期未改善","設施場所年度參觀人數未達一萬人次、門票收費高於同類型場所平均水準、未於社群媒體定期發布活動訊息、未與鄰近學校簽訂合作備忘錄等情形","設施場所之環境教育人員請假超過三十日、每季執行成果申報遲交三日以上、未參加中央主管機關舉辦之觀摩研習活動、網站未設置英文版及日文版頁面等情形","設施場所之營業額連續二年衰退、未辦理員工年度健康檢查、未投保公共意外責任保險、未設置無障礙設施及哺集乳室等未符法定基準情形"],"a",
 "第17條第1項：設施場所有環境教育執行成果內容不實、無正當理由拒絕訪查或提供必要資料、申請人喪失所有權管理權或使用權、核准設立登記證明經撤銷或廢止、經命停止營運或營運許可經撤銷廢止、未提供環境教育服務持續達一年以上、評鑑不合格經命限期改善屆期未改善、疏於維護管理影響服務品質經命限期改善屆期未改善、專業人力課程方案或經營管理與申請文件不符經命限期改善屆期未改善等情形之一者，得廢止其認證。第2項並定不再經營者應以書面申請廢止。",
 "In which cases may a facility certification be annulled?",
 ["False performance reports, refusing inspection or data without cause, losing ownership or use rights, ceasing services for over a year, or failing assessment and not improving in time","Annual visitors below ten thousand, ticket prices above the average for similar sites, no regular social media posts, or no memorandum of cooperation with nearby schools","Personnel taking over thirty days of leave, filing a quarterly performance report three days late, not joining the authority observation and study events, or having no English website pages","Turnover falling for two consecutive years, no annual staff health checks, no public liability insurance, or lacking accessible facilities and a nursing room"],
 "Article 17, Paragraph 1."),

(S,"第18條",1,"設施場所-資訊公開",
 "設施場所認證之核發、撤銷或廢止，應如何公開？",
 ["應公開於中央主管機關之網站","應刊登於政府公報及全國性報紙","應張貼於設施場所所在地之鄉鎮市區公所","應於設施場所入口處公告三十日以上"],"a",
 "第18條：設施場所認證之核發、撤銷或廢止，應公開於中央主管機關之網站。第8條第2項並要求認證證明文件應陳列於設施場所明顯處。",
 "How must the issuance, revocation or annulment of certification be published?",
 ["It must be published on the website of the central competent authority","It must be published in the government gazette and a national newspaper","It must be posted at the township office where the facility is located","It must be posted at the facility entrance for at least thirty days"],
 "Article 18."),

(S,"第19條",2,"設施場所-委託辦理",
 "中央主管機關得委託中央目的事業主管機關辦理之設施場所事項及其收費基準為何？",
 ["得委託辦理其所屬或主管業務範圍之設施場所認證、評鑑、撤銷、廢止及管理事項；受委託機關辦理認證審查之收費基準準用第五條及第九條第一項規定","得委託辦理設施場所之認證及評鑑事項，但撤銷、廢止及管理事項仍應由中央主管機關自行辦理；受委託機關得自行訂定收費基準並公告實施","得委託直轄市或縣市主管機關辦理轄內設施場所之全部認證及管理事項；受委託機關辦理認證審查之收費基準由各該地方政府自治條例定之","得委託學術團體或專業評鑑機構辦理設施場所之認證及撤銷廢止事項；受委託團體辦理認證審查之收費得由其與申請人自行議定後收取"],"a",
 "第19條第1項：中央主管機關得委託中央目的事業主管機關依本辦法之規定，辦理其所屬或主管業務範圍之設施場所認證、評鑑、撤銷、廢止及管理事項。第2項：受委託機關辦理設施場所認證審查之收費基準，準用第5條及第9條第1項規定。",
 "What may be entrusted to the relevant central industry authority, and at what fees?",
 ["Certification, assessment, revocation, annulment and management of facilities in its own remit; its review fees follow Article 5 and Article 9, Paragraph 1","Only certification and assessment may be entrusted while revocation, annulment and management stay with the central authority; fees are set by the entrusted agency","All certification and management of facilities in a locality may be entrusted to municipal or county authorities; their fees are set by local self-government ordinance","Certification, revocation and annulment may be entrusted to academic or professional assessment bodies; their fees are negotiated directly with each applicant"],
 "Article 19."),

(S,"第20條",1,"設施場所-施行日",
 "環境教育設施場所認證及管理辦法之施行日期規定為何？",
 ["自發布日施行","自發布後三個月施行","自發布後六個月施行","自發布後一年施行"],"a",
 "第20條：本辦法自發布日施行。本辦法依環境教育法第14條第3項訂定，第9條並定認證有效期限為五年、每次展延五年。",
 "When do these Regulations take effect?",
 ["On the date of promulgation","Three months after promulgation","Six months after promulgation","One year after promulgation"],
 "Article 20."),

(G,"第1條",1,"環教機構-授權依據",
 "環境教育機構認證及管理辦法係依據下列何項規定訂定？",
 ["環境教育法第十條第三項","環境教育法第十四條第三項","環境教育法第二十四條第二項","環境教育法第十九條第三項規定"],"a",
 "第1條：本辦法依環境教育法第10條第3項規定訂定之。環境教育設施場所認證及管理辦法則依本法第14條第3項訂定。第21條並定本辦法自發布日施行。",
 "Under which provision are the Environmental Education Institution Regulations issued?",
 ["Article 10, Paragraph 3 of the Environmental Education Act","Article 14, Paragraph 3 of the Environmental Education Act","Article 24, Paragraph 2 of the Environmental Education Act","Article 19, Paragraph 3 of the Environmental Education Act"],
 "Article 1."),

(G,"第2條",1,"環教機構-核發機關",
 "本辦法所稱「核發機關」係指何者？",
 ["依本法第十條第一項規定，辦理環境教育機構認證之中央主管機關及中央目的事業主管機關","依本法第十條第一項規定，辦理環境教育機構認證之直轄市及縣（市）政府環境保護局","依本法第十四條規定，受中央主管機關委託辦理認證審查作業之學術團體或專業評鑑機構","依本法第十九條規定，辦理環境講習業務之各級主管機關及其所屬環境教育設施場所單位"],"a",
 "第2條：本辦法所稱核發機關，指依本法第10條第1項規定，辦理環境教育機構認證之中央主管機關及中央目的事業主管機關。第20條並定認證之核發、撤銷或廢止應公開於核發機關之網站。",
 "Who is the issuing agency under these Regulations?",
 ["The central competent authority and the relevant central industry authority that certify environmental education institutions under Article 10, Paragraph 1","The municipal and county environmental protection bureaus that certify environmental education institutions under Article 10, Paragraph 1","The academic groups or professional assessment bodies commissioned by the central competent authority to conduct certification reviews under Article 14","The competent authorities at all levels and their facilities that run environmental lectures under Article 19 of the Act"],
 "Article 2."),

(G,"第3條",2,"環教機構-申請資格",
 "申請環境教育機構認證之資格，應符合下列何者之一？",
 ["已設置專業人員訓練或研究單位之各級政府機關（構）、設有環境相關系所或具辦理相關訓練設施之大學或獨立學院、曾辦理環境相關訓練或研習課程一年累計達八十小時以上依法設立之法人","已設置專業人員訓練或研究單位之各級政府機關（構）、設有任何系所之大學或獨立學院、曾辦理環境相關訓練或研習課程一年累計達二十小時以上依法設立之法人或自然人","已取得環境教育設施場所認證滿三年之單位、設有環境相關系所之高級中等學校、曾辦理環境相關訓練或研習課程一年累計達一百六十小時以上之營利事業機構","已依環境教育法取得環境教育人員認證之自然人、設有環境相關系所之大學附屬機構、曾自行辦理環境相關訓練課程累計達八十小時以上之人民團體或社區組織"],"a",
 "第3條：申請環境教育機構認證，其資格應符合下列規定之一：一、已設置專業人員訓練或研究單位之各級政府機關（構）；二、設有環境相關系所或具有辦理相關訓練設施之大學或獨立學院；三、曾自行或受託辦理環境相關訓練或研習課程，一年累計達八十小時以上依法設立之法人。",
 "Who is eligible to apply for institution certification?",
 ["Government agencies with a training or research unit, universities or colleges with environmental departments or training facilities, or legal persons that ran at least eighty hours of related courses in a year","Government agencies with a training or research unit, universities or colleges with any department at all, or legal or natural persons that ran at least twenty hours of related courses in a year","Units certified as an education facility for three years, senior high schools with environmental departments, or profit-making businesses that ran at least one hundred sixty hours of courses","Individuals certified as environmental education personnel, university affiliates with environmental departments, or civic groups or community organizations that ran at least eighty hours of related courses"],
 "Article 3."),

(G,"第4條",3,"環教機構-申請文件",
 "申請環境教育機構認證所檢具之計畫書，應包括之內容為何？",
 ["環境教育專業人力配置說明（至少應配置一名依本法取得認證之環境教育人員）、預定開辦之課程科目授課師資及授課章節大綱、經營管理計畫含配合推廣環境政策相關執行措施","環境現況及自然或人文特色主題內容之說明、與保護環境連結之環境教育課程方案、近三年辦理環境教育相關證明、安全維護及環境負荷評估與財務計畫等","訓練場所之土地及建物登記謄本、消防安全設備檢查合格證明、公共意外責任保險單影本、學員意外險投保證明及訓練場所平面配置圖說等文件","最近三年之財務報表及會計師查核簽證報告、歷年開班班次及結訓人數統計、學員滿意度調查結果、收費標準表及與其他機構簽訂之合作契約"],"a",
 "第4條第1項第3款：計畫書內容為環境教育專業人力配置說明（至少應配置一名依本法取得認證之環境教育人員）、預定開辦之課程科目、授課師資及授課章節大綱、經營管理計畫（含配合推廣環境政策相關執行措施）。第2款並要求檢具訓練場所所有權或使用權證明、負責人身分證明及符合第3條資格之證明。",
 "What must the plan submitted with an institution certification application contain?",
 ["Professional staffing with at least one certified environmental education person, the planned course subjects, instructors and syllabi, and a management plan including policy promotion measures","Current environmental conditions and thematic features, curriculum programmes linked to environmental protection, three-year activity proof, safety and environmental load and financial plans","Land and building registration transcripts for the venue, fire safety inspection certificates, public liability insurance, student accident insurance, and venue floor plans","Three years of financial statements with auditor reports, class and graduate statistics, student satisfaction surveys, the fee schedule, and cooperation contracts"],
 "Article 4, Paragraph 1, Subparagraph 3."),

(G,"第4條",3,"環教機構-師資資格",
 "環境教育機構預定開辦課程之授課師資，應具備之資格為何？",
 ["應具三年以上環境教育相關工作經驗，並符合現任或曾任大專院校環境相關系所助理教授以上、現任或曾任職於各級環境主管機關、取得環境教育教學人員認證之一","應具一年以上環境教育相關工作經驗，並符合現任或曾任大專院校任何系所講師以上、現任或曾任職於各級政府機關、取得環境教育人員任一類別認證之一","應具五年以上環境教育相關工作經驗，並符合現任大專院校環境相關系所教授、現任各級環境主管機關簡任職以上人員、取得國際環境教育證照之一","應具三年以上任何行業工作經驗，並符合曾參加環境教育相關研習八十小時以上、經機構負責人書面推薦、取得環境教育設施場所服務證明之一"],"a",
 "第4條第3項：授課師資應具三年以上環境教育相關工作經驗，並符合下列資格之一：一、現任或曾任職於公私立大專院校之環境相關系所助理教授以上；二、現任或曾任職於各級環境主管機關；三、取得環境教育教學人員認證。第2項並定環境教育人員連續三年以上未配置者應檢附一年內三小時以上法規或政策訓練證明。",
 "What qualifications must an institution instructor hold?",
 ["At least three years of related work experience, plus being or having been an assistant professor or above in an environmental department, serving in an environmental authority, or holding teaching personnel certification","At least one year of related work experience, plus being or having been a lecturer or above in any department, serving in any government agency, or holding any category of personnel certification","At least five years of related work experience, plus being a current professor in an environmental department, a senior-rank officer in an environmental authority, or holding an international licence","At least three years of work experience in any industry at all, plus having attended eighty hours of related seminars, a written recommendation from the head of the institution, or proof of service at a certified facility"],
 "Article 4, Paragraph 3."),

(G,"第5條",1,"環教機構-審查費",
 "申請環境教育機構認證時，應繳納之審查費為多少？",
 ["新臺幣一萬元","新臺幣五千元","新臺幣二千五百元","新臺幣三萬元整"],"a",
 "第5條：申請人依第4條提出申請時，應繳納審查費新臺幣一萬元。第9條第1項展延審查費為新臺幣五千元；第10條並定除依規費法規定得申請退還外，不得以任何理由要求退費或保留。",
 "What review fee is payable when applying for institution certification?",
 ["NT$10,000","NT$5,000","NT$2,500","NT$30,000"],
 "Article 5."),

(G,"第6條",2,"環教機構-審查期限",
 "核發機關辦理環境教育機構認證審查之期限及現勘規定為何？",
 ["應於收到申請文件及審查費次日起三個月內完成審查，必要時得延長合計不得逾六個月，補正日數不計入審查期間；審查時認有必要者得至環境教育機構辦理現勘","應於收到申請文件及審查費次日起六個月內完成審查，必要時得延長合計不得逾一年，補正日數計入審查期間內；審查時一律應至環境教育機構辦理現場勘查","應於收到申請文件及審查費次日起一個月內完成審查，不得延長審查期間，補正日數計入審查期間；審查時不得至環境教育機構辦理任何形式之現勘作業","應於收到申請文件及審查費次日起九十日內完成審查，必要時得延長合計不得逾一百八十日；現勘應委由地方主管機關代為辦理並作成書面報告函送"],"a",
 "第6條第1項：核發機關應於收到申請文件及審查費之次日起三個月內完成環境教育機構認證審查；經審查應補正者應通知限期補正，逾期未補正、補正不完全或無法補正者駁回其申請。第2項：審查期間必要時得延長之，合計不得逾六個月；補正日數不計入審查期間。第3項：核發機關於審查時認有必要者，得至環境教育機構辦理現勘。",
 "What review period and site inspection rules apply to institution certification?",
 ["Three months from the day after documents and fee are received, extendable to no more than six months, supplementation days excluded; a site inspection may be made if needed","Six months from the day after documents and fee are received, extendable to no more than one year, supplementation days counted; a site inspection is always mandatory","One month from the day after documents and fee are received with no extension, supplementation days counted; no site inspection of the institution is permitted at all","Ninety days from the day after documents and fee are received, extendable to no more than one hundred eighty days; the local authority conducts the inspection instead"],
 "Article 6."),

(G,"第7條",2,"環教機構-審查會",
 "核發機關辦理環境教育機構認證審查時，關於審查組織及程序之規定為何？",
 ["應邀集相關機關及專家學者參與審查並得成立審查會；審查會開會前得徵詢專家學者及相關機關團體意見，召開初審會議並將初審結果提報審查會審查","應由核發機關指派二名以上承辦人員共同書面審查後陳核；不得邀集外部專家學者參與審查，亦不得成立審查會或召開初審會議等程序","應委由中央主管機關統一辦理審查，中央目的事業主管機關僅得提供意見；審查會之組成及初審程序由中央主管機關另以作業要點定之","應由申請人自行委託三名以上專家學者出具審查意見書送核發機關；核發機關依該意見書逕予核定，無須另行召開任何審查會議"],"a",
 "第7條第1項：核發機關辦理環境教育機構之認證，應邀集相關機關及專家學者參與審查，並得成立審查會辦理相關作業。第2項：審查會開會前，得徵詢有關專家學者及相關機關、團體意見，召開初審會議，初審結果提報審查會審查。",
 "How is the institution certification review organized?",
 ["Relevant agencies and experts are invited and a review panel may be set up; before it meets, opinions may be sought and a preliminary meeting held whose results go to the panel","Two or more staff of the issuing agency jointly review the documents and submit them for approval; no outside experts, review panel or preliminary meeting may be involved at all","The central competent authority conducts all reviews and industry authorities may only comment; the panel and preliminary process are set by separate guidelines","The applicant commissions three or more outside experts to issue written review opinions, on which the issuing agency decides without convening any review meeting"],
 "Article 7."),

(G,"第8條",2,"環教機構-認證文件",
 "核發機關核發之環境教育機構認證證明文件，其應記載事項為何？",
 ["環境教育機構名稱及地址、負責人姓名、核發機關、核可事項、核准日期及字號、有效期限；並應陳列於環境教育機構明顯處","環境教育機構名稱及地址、授課師資名冊及學經歷、課程科目及時數、收費標準、學員人數上限；並應陳列於機構明顯處","環境教育機構名稱及地址、訓練場所面積及容納人數、消防安全設備、緊急疏散路線圖；並應公告於核發機關之網站上","環境教育機構名稱及地址、最近一次評鑑等級及分數、歷年開班數及結訓人數、財務概況；並應陳列於機構入口處"],"a",
 "第8條第1項：認證證明文件應記載環境教育機構名稱及地址、負責人姓名、核發機關、核可事項、核准日期及字號、有效期限。第2項：認證證明文件應陳列於環境教育機構明顯處。第20條並定認證之核發、撤銷或廢止應公開於核發機關之網站。",
 "What must the institution certification document state?",
 ["The institution name and address, the representative name, the issuing agency, the approved items, the approval date and number, and validity; displayed conspicuously","The institution name and address, the instructor roster with credentials, course subjects and hours, fees and student caps; displayed conspicuously at the institution","The institution name and address, venue area and capacity, fire safety equipment and evacuation route maps; published on the website of the issuing agency","The institution name and address, the latest assessment grade and score, class and graduate statistics and finances; displayed at the institution entrance"],
 "Article 8."),

(G,"第9條",3,"環教機構-展延",
 "環境教育機構認證之有效期限及展延申請規定為何？",
 ["有效期限為五年；期限屆滿前三至六個月期間內得檢具申請書、經營管理計畫、最近一次評鑑建議回覆表等文件並繳交展延審查費新臺幣五千元申請展延，每次展延有效期限為五年","有效期限為三年；期限屆滿前三至六個月期間內得檢具申請書、經營管理計畫、最近一次評鑑建議回覆表等文件並繳交展延審查費新臺幣一萬元申請展延，每次展延有效期限為三年","有效期限為五年；期限屆滿後三個月內得補行檢具申請書及經營管理計畫等文件並繳交展延審查費新臺幣二千五百元申請展延，每次展延之有效期限則為十年","有效期限為十年；期限屆滿前一個月內得檢具申請書及最近一次評鑑建議回覆表申請展延且免繳交任何展延審查費，每次展延之有效期限由核發機關個案核定"],"a",
 "第9條第1項：環境教育機構之認證有效期限為五年；期限屆滿前三至六個月期間內，得檢具申請書、經營管理計畫、最近一次評鑑建議回覆表及其他經核發機關指定之文件，並繳交展延審查費新臺幣五千元，向核發機關申請展延；每次展延之有效期限為五年。第5項並定審查期限三個月，必要時得延長合計不得逾六個月。",
 "What are the validity and renewal rules for institution certification?",
 ["Valid five years; apply three to six months before expiry with the application, management plan and latest assessment response, paying an NT$5,000 renewal fee; each renewal lasts five years","Valid three years; apply three to six months before expiry with the application, management plan and latest assessment response, paying an NT$10,000 renewal fee; each renewal lasts three years","Valid five years; apply within three months after expiry with the application and management plan, paying an NT$2,500 renewal fee; each renewal then lasts for ten years","Valid ten years; apply within one month before expiry with the application and latest assessment response with no renewal fee; each renewal period is decided case by case"],
 "Article 9, Paragraph 1."),

(G,"第9條",3,"環教機構-展延效果",
 "環境教育機構未於規定期間申請展延或未於期限屆滿前申請展延者，其效果為何？",
 ["未於規定期間申請者，核發機關於期限屆滿尚未完成審查時，應自期限屆滿時起停止以環境教育機構名義經營業務；未於期限屆滿前申請者，認證於期限屆滿時失其效力","未於規定期間申請者，仍得於審查期間內依原認證內容繼續經營業務；未於期限屆滿前申請者，得於屆滿後三個月內補行申請，其認證效力並不因此受影響","未於規定期間申請者，核發機關應逕予撤銷其認證並公開於網站；未於期限屆滿前申請者，其認證自動展延一年，俟次年再行申請展延即可繼續營運","未於規定期間申請者，應加倍繳納展延審查費後即得繼續營運；未於期限屆滿前申請者，核發機關應命其限期補行申請，屆期未申請者始失其效力"],"a",
 "第9條第2項：依規定期間申請展延者，核發機關於有效期限屆滿尚未完成審查時，環境教育機構於審查期間內得依原認證內容辦理。第3項：未於第1項規定期間申請展延者，於期限屆滿尚未完成審查時，應自期限屆滿時起停止以環境教育機構名義經營環境教育業務。第4項：未於期限屆滿前申請展延者，於期限屆滿時認證失其效力，如需繼續經營應重新申請認證。",
 "What follows when institution renewal is applied for late or not at all?",
 ["If applied late and review is unfinished at expiry, operating under the institution name must stop from expiry; if never applied for, the certification lapses at expiry","If applied late, business may continue under the original certification during review; if never applied for, a late application within three months preserves the effect","If applied late, the agency revokes the certification and publishes it online; if never applied for, the certification is automatically extended for one further year","If applied late, doubling the renewal fee allows continued operation; if never applied for, the agency must order a late application before any lapse occurs"],
 "Article 9, Paragraphs 3 and 4."),

(G,"第10條",1,"環教機構-規費退還",
 "依規定繳交之環境教育機構認證審查費及展延審查費，得否要求退費？",
 ["除依規費法規定得申請退還外，不得以任何理由要求退費或保留","申請案件經駁回者，得申請退還已繳納審查費之半數金額","申請人於審查完成前撤回申請者，得申請全額退還審查費","得由申請人選擇退費或保留至次年度申請時抵充審查費用"],"a",
 "第10條：依第5條及第9條第1項規定繳交之審查費，除依規費法規定得申請退還外，不得以任何理由要求退費或保留。第5條認證審查費為新臺幣一萬元，第9條第1項展延審查費為新臺幣五千元。",
 "May the institution review or renewal fee be refunded?",
 ["Except where the Fee Act allows a refund, no refund or carry-over may be demanded on any ground","If the application is rejected, half of the review fee already paid may be claimed back","If the applicant withdraws before the review ends, the full review fee may be refunded","The applicant may choose a refund or carry the fee over to next year application"],
 "Article 10."),

(G,"第11條",1,"環教機構-調訓",
 "核發機關對依本辦法配置之環境教育人員，有何調訓權限？",
 ["得於必要時調訓該等人員，環境教育機構不得以任何方式妨礙其參訓","得於必要時調訓該等人員，惟環境教育機構得以開班在即為由拒絕派員","僅得於認證審查期間要求該等人員參訓，取得認證後即不得再行調訓","應由環境教育機構自行辦理內部訓練，核發機關不得逕行調訓該人員"],"a",
 "第11條第1項：核發機關於必要時得調訓依本辦法配置之環境教育人員。第2項：環境教育機構不得以任何方式妨礙前項人員參訓。第4條第1項第3款第1目並要求至少配置一名依本法取得認證之環境教育人員。",
 "What power does the issuing agency have to call assigned personnel for training?",
 ["It may call them for training when necessary, and the institution may not obstruct their attendance in any way","It may call them for training when necessary, but the institution may refuse because a class is about to start","It may require attendance only during the certification review, and never after certification is granted","The institution must run its own internal training, and the agency may not summon the personnel"],
 "Article 11."),

(G,"第12條",2,"環教機構-文件異動",
 "環境教育機構申請認證所送文件及認證證明文件記載事項有異動時，應如何辦理？",
 ["除預定開辦之課程科目授課師資及授課章節大綱之文件應於報請核發機關核准後始得變更外，其餘應於異動後十五日內報請核發機關備查","除環境教育專業人力配置說明之文件應於報請核發機關核准後始得變更外，其餘應於異動後三十日內報請核發機關備查並副知中央主管機關","所有異動文件均應於報請核發機關核准後始得變更，未經核准而逕行變更者，核發機關應逕予撤銷其環境教育機構之認證資格","所有異動文件均得由環境教育機構自行變更並留存備查，僅需於每季執行成果申報時併同說明其異動之內容及理由即可辦理"],"a",
 "第12條：環境教育機構申請認證所送文件及認證證明文件記載事項有異動時，除第4條第1項第3款第2目之文件（預定開辦之課程科目、授課師資及授課章節大綱）應於報請核發機關核准後始得變更外，應於異動後十五日內報請核發機關備查。第19條第1項第9款並定課程科目授課師資等與申請文件不符經限期改善屆期未改善者得廢止認證。",
 "How must changes to an institution submitted documents be handled?",
 ["Except the planned course subjects, instructors and syllabi, which need prior approval before change, changes are filed for recordation within fifteen days","Except the professional staffing statement, which needs prior approval before change, changes are filed for recordation within thirty days with a copy to the authority","All changed documents require prior approval, and changing them without approval leads the issuing agency to revoke the institution certification","All documents may be changed by the institution itself and merely explained with reasons in the quarterly performance report"],
 "Article 12."),

(G,"第13條",3,"環教機構-開班備查",
 "環境教育機構辦理環境教育人員訓練及環境講習之備查期限規定為何？",
 ["人員訓練應於開班十日前將開班日期及課程表送核發機關備查，並於開班後七日內將參訓學員名冊送備查；環境講習應於開班一個月前將日期送委託講習機關備查","人員訓練應於開班三十日前將開班日期及課程表送核發機關備查，並於結訓後三十日內將學員名冊送備查；環境講習應於開班七日前將日期送委託講習機關備查","人員訓練應於開班後十日內將開班日期及課程表送核發機關備查，學員名冊則免送備查；環境講習應於結束後一個月內將辦理情形送委託講習機關備查","人員訓練及環境講習均應於開班十日前將日期課程表及學員名冊一併送核發機關備查；委託講習機關不介入備查作業，亦不受理任何備查文件之送件"],"a",
 "第13條第1項：環境教育機構應於環境教育人員訓練開班十日前將開班日期及課程表送核發機關備查，並於開班後七日內將參訓學員名冊送核發機關備查。第2項：應於環境講習開班一個月前將環境講習日期送委託辦理環境講習之主管機關備查。第3項：前二項檢送之資料有異動者，應送核發機關或委託講習機關備查。",
 "What filing deadlines apply to personnel training and environmental lectures?",
 ["Training: file the date and syllabus ten days before opening and the student roster within seven days after; lectures: file the date one month before opening with the commissioning agency","Training: file the date and syllabus thirty days before opening and the roster within thirty days after completion; lectures: file the date seven days before opening with that agency","Training: file the date and syllabus within ten days after opening, with no roster required; lectures: report the outcome within one month after they end to the commissioning agency","Training and lectures alike: file dates, syllabi and rosters ten days before opening with the issuing agency; the commissioning agency has no role in the filing process"],
 "Article 13."),

(G,"第14條",1,"環教機構-成果申報",
 "環境教育機構應如何申報環境教育執行成果？",
 ["應於每季依核發機關要求之格式，以網路傳輸方式申報前一季環境教育執行成果","應於每年一月底前依核發機關要求之格式，以書面方式申報前一年度執行成果","應於每次開班結訓後三十日內依核發機關要求之格式，以電子郵件方式申報","應於每月底前依核發機關要求之格式，以網路傳輸方式申報當月執行成果"],"a",
 "第14條：環境教育機構應於每季依核發機關要求之格式，以網路傳輸方式申報前一季環境教育執行成果。第13條並定人員訓練及環境講習之開班備查期限；第16條定核發機關得隨時派員訪查。",
 "How must an institution report its environmental education performance?",
 ["Quarterly, in the format required by the issuing agency, transmitted online for the preceding quarter","By the end of January each year, in the format required by the issuing agency, filed in paper form","Within thirty days after each class ends, in the format required by the issuing agency, sent by e-mail","By the end of each month, in the format required by the issuing agency, transmitted online for that month"],
 "Article 14."),

(G,"第15條",1,"環教機構-收費",
 "環境教育機構辦理環境教育人員訓練之收費規定為何？",
 ["得向參加人員收取必要之費用，其收費基準上限由中央主管機關定之","得向參加人員收取必要之費用，其收費基準由環境教育機構自行訂定","不得向參加人員收取任何費用，訓練經費應由核發機關全額補助支應","得向參加人員收取必要之費用，其收費基準上限由核發機關逐案核定"],"a",
 "第15條第1項：環境教育機構辦理環境教育人員訓練，得向參加人員收取必要之費用。第2項：前項收費基準上限由中央主管機關定之。第5條並定申請認證應繳納審查費新臺幣一萬元。",
 "What are the fee rules for personnel training run by an institution?",
 ["Necessary fees may be charged to participants, with the upper limit set by the central competent authority","Necessary fees may be charged to participants, with the fee schedule set by the institution itself","No fee may be charged to participants, and the issuing agency must fully subsidize the training","Necessary fees may be charged, with the upper limit approved case by case by the issuing agency"],
 "Article 15."),

(G,"第16條",1,"環教機構-訪查",
 "核發機關對環境教育機構有何訪查權限？",
 ["得隨時派員訪查，並命其就環境教育人員訓練或環境講習實施狀況提供必要資料","得於每年評鑑期間派員訪查，並應於訪查前十四日以書面通知該環境教育機構","僅得就機構所送之季報表進行書面查核，不得派員進入機構辦理現場訪查作業","應委由中央主管機關統一派員訪查，中央目的事業主管機關不得自行派員訪查"],"a",
 "第16條：核發機關得隨時派員訪查環境教育機構，並命其就環境教育人員訓練或環境講習實施狀況提供必要資料。第19條第1項第1款：無正當理由拒絕核發機關訪查或提供必要資料者，核發機關得廢止其認證。",
 "What inspection powers does the issuing agency have over an institution?",
 ["Officers may visit at any time and require necessary data on personnel training or environmental lectures","Officers visit during the annual assessment period, with fourteen days written notice given beforehand","Only the quarterly reports may be reviewed on paper, with no on-site visits to the institution allowed","The central competent authority alone may send officers, and industry authorities may not do so"],
 "Article 16."),

(G,"第17條",2,"環教機構-評鑑",
 "核發機關對環境教育機構實施評鑑之時點及受評鑑單位之義務為何？",
 ["得自行或委託學術團體或專業評鑑機構，於通過認證或展延之日當年起算第三年實施評鑑；受評鑑單位需提出評鑑自評報告，其格式由核發機關定之","得自行或委託學術團體或專業評鑑機構，於通過認證或展延之日當年起算第五年實施評鑑；受評鑑單位僅需提供歷年開班紀錄供查核無須自評","應由核發機關自行辦理不得委託任何團體，於通過認證之日當年起算第一年實施評鑑；受評鑑單位需提出財務報表及會計師查核簽證報告","應由環境教育機構自行委託專業評鑑機構於每年辦理評鑑；評鑑結果及自評報告由機構自行留存，無須報請核發機關備查或審核"],"a",
 "第17條第1項：核發機關得自行或委託學術團體或專業評鑑機構，於通過認證或展延之日當年起算第三年，對環境教育機構實施評鑑。第2項：受評鑑單位需提出評鑑自評報告，其格式由核發機關定之。第19條第1項第7款並定評鑑不合格經命限期改善屆期未改善完成者得廢止認證。",
 "When is an institution assessed and what must it submit?",
 ["The agency may assess itself or through academic or professional bodies in the third year from certification or renewal; the assessed unit files a self-assessment report in the set format","The agency may assess itself or through academic or professional bodies in the fifth year from certification or renewal; the unit need only supply past class records for checking","The agency must assess by itself without any delegation in the first year from certification; the assessed unit files financial statements and a certified public accountant report","The institution must commission a professional assessment body annually; the results and self-assessment stay with the institution without any filing to the agency"],
 "Article 17."),

(G,"第18條",1,"環教機構-撤銷認證",
 "環境教育機構檢送之申請文件有虛偽不實者，核發機關應如何處理？",
 ["應撤銷其認證","得命其限期改善，屆期未改善完成始撤銷其認證","應處以罰鍰並命其於三十日內重新檢送正確文件","得停止其招訓學員六個月，期滿後認證回復效力"],"a",
 "第18條：環境教育機構依第4條第1項、第2項及第9條第1項檢送之申請文件有虛偽不實者，核發機關應撤銷其認證。第19條則規定得廢止認證之十款情形；第20條並定認證之核發、撤銷或廢止應公開於核發機關網站。",
 "What happens if an institution submits false application documents?",
 ["The certification must be revoked","An improvement order comes first, with revocation only if unremedied","A fine is imposed with an order to refile correct documents within thirty days","Student recruitment is suspended for six months and then certification revives"],
 "Article 18."),

(G,"第19條",3,"環教機構-廢止認證",
 "核發機關得廢止環境教育機構認證之情形，下列何者符合規定？",
 ["無正當理由拒絕訪查或提供必要資料、喪失對訓練場所之所有權或使用權、以不實廣告或內容招訓學員、無故自行縮減課程或時數、非實際執行人員訓練或環境講習","訓練班次之學員報名人數未達開班人數下限、收費金額高於同類機構之平均水準、未於報章雜誌刊登招生廣告、未設置學員意見反映信箱等情形","授課師資請假由他人代課、課程表印製錯誤、未提供學員午餐及交通接駁服務、訓練場所未設置飲水機及自動販賣機等服務品質面之情形","機構負責人變更未於三日內公告、每季執行成果申報遲交一日、未參加核發機關舉辦之聯繫會報、未編製年度工作計畫書等行政程序事項"],"a",
 "第19條第1項：環境教育機構有無正當理由拒絕核發機關訪查或提供必要資料、喪失對訓練場所之所有權或使用權、政府機關核准設立登記證明文件經撤銷或廢止、以不實廣告或內容招訓學員、無故自行縮減課程或時數、非實際執行環境教育人員訓練或環境講習、評鑑不合格經命限期改善屆期未改善完成、疏於維護管理致影響服務品質經命限期改善屆期未改善完成、專業人力課程科目授課師資或實際經營管理與申請文件不符經命限期改善屆期未改善完成等情形之一者，得廢止其認證。第2項並定不再經營者應以書面申請廢止。",
 "In which cases may an institution certification be annulled?",
 ["Refusing inspection or data without cause, losing rights to the training venue, recruiting with false advertising, cutting courses or hours without cause, or not actually running the training","Enrolment falling below the minimum class size, charging above the average for similar institutions, not advertising in newspapers, or having no student feedback mailbox","An instructor taking leave and being replaced by another, misprinted course syllabi, not providing lunch or shuttle bus services, or having no water dispenser or vending machine at the training venue","Not announcing a change of representative within three days, filing a quarterly report one day late, missing liaison meetings, or not preparing an annual work plan"],
 "Article 19, Paragraph 1."),

(G,"第20條",1,"環教機構-資訊公開",
 "環境教育機構認證之核發、撤銷或廢止，應如何公開？",
 ["應公開於核發機關之網站","應刊登於政府公報及全國性報紙","應函知各級學校及地方主管機關轉知","應於環境教育機構門口公告三十日"],"a",
 "第20條：環境教育機構認證之核發、撤銷或廢止，應公開於核發機關之網站。第2條並定核發機關指辦理環境教育機構認證之中央主管機關及中央目的事業主管機關；第8條第2項並要求認證證明文件應陳列於機構明顯處。",
 "How must the issuance, revocation or annulment of institution certification be published?",
 ["It must be published on the website of the issuing agency","It must be published in the government gazette and a national newspaper","It must be notified to schools and local authorities for onward notice","It must be posted at the institution entrance for thirty days"],
 "Article 20."),

(G,"第21條",1,"環教機構-施行日",
 "環境教育機構認證及管理辦法之施行日期規定為何？",
 ["自發布日施行","自發布後三個月施行","自發布後六個月施行","自發布後一年施行"],"a",
 "第21條：本辦法自發布日施行。本辦法依環境教育法第10條第3項訂定，第9條並定認證有效期限為五年、每次展延之有效期限亦為五年。",
 "When do the Environmental Education Institution Regulations take effect?",
 ["On the date of promulgation","Three months after promulgation","Six months after promulgation","One year after promulgation"],
 "Article 21."),
]
